select
a.model_id,
a.model_name,
a.device_type,
a.remark
from t_std_metemodel a
where 1 = 1
 and a.model_id = #{modelId, jdbcType=BIGINT}
 and a.model_name = #{modelName, jdbcType=VARCHAR}
 and a.device_type = #{deviceType, jdbcType=INTEGER}
 and a.remark = #{remark, jdbcType=VARCHAR}

